using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private Dictionary<string, decimal> _prices = new(StringComparer.OrdinalIgnoreCase);

    // Reverse index: category → list of product codes
    private Dictionary<string, List<string>> _categoryIndex = new(StringComparer.OrdinalIgnoreCase);

    // Frozen (read-optimized) snapshots for lookups
    private FrozenDictionary<string, string> _frozenCategories = FrozenDictionary<string, string>.Empty;
    private FrozenDictionary<string, decimal> _frozenPrices = FrozenDictionary<string, decimal>.Empty;
    private FrozenDictionary<string, string[]> _frozenCategoryIndex = FrozenDictionary<string, string[]>.Empty;

    public void AddProduct(string code, string category, decimal price)
    {
        _categories[code] = category;
        _prices[code] = price;

        if (!_categoryIndex.TryGetValue(category, out var list))
        {
            list = new List<string>();
            _categoryIndex[category] = list;
        }
        list.Add(code);
    }

    /// <summary>
    /// Freezes internal dictionaries into read-optimized structures.
    /// Call after bulk loading is complete for maximum lookup throughput.
    /// </summary>
    public void Freeze()
    {
        _frozenCategories = _categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenPrices = _prices.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenCategoryIndex = _categoryIndex.ToFrozenDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.ToArray(),
            StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
        => _frozenCategories.TryGetValue(code, out var cat) ? cat : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        var prices = _frozenPrices;
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    /// <summary>
    /// Returns all product codes in the given category using O(1) index lookup.
    /// </summary>
    public List<string> GetProductsByCategory(string category)
    {
        if (_frozenCategoryIndex.TryGetValue(category, out var codes))
            return new List<string>(codes);
        return new List<string>();
    }
}

